use soroban_sdk::{contract, contractimpl, contracttype, Address, Env, Symbol, Vec, log, panic_with_error}; use crate::error::Error; use crate::types::{Escrow, EscrowStatus, SplitRecipient, ProtocolConfig}; const DAY_IN_LEDGERS: u32 = 17280; const INSTANCE_BUMP_AMOUNT: u32 = 7 * DAY_IN_LEDGERS; const INSTANCE_LIFETIME_THRESHOLD: u32 = DAY_IN_LEDGERS; #[contract] pub struct EscrowContract; #[contractimpl] impl EscrowContract { pub fn __constructor( env: Env, admin: Address, sponsor: Address, token: Address, amount: i128, deadline: u64, protocol_config: ProtocolConfig, ) { admin.require_auth(); if amount <= 0 { panic_with_error!(&env, Error::InvalidAmount); } let now = env.ledger().timestamp(); if deadline <= now { panic_with_error!(&env, Error::DeadlineInPast); } let escrow = Escrow { admin, sponsor, token, amount, deadline, status: EscrowStatus::Funded, protocol_config, }; env.storage().instance().set(&DataKey::Escrow, &escrow); env.storage().instance().extend_ttl(INSTANCE_LIFETIME_THRESHOLD, INSTANCE_BUMP_AMOUNT); } pub fn release(env: Env, recipients: Vec<SplitRecipient>) -> Vec<(Address, i128)> { let mut escrow: Escrow = env.storage().instance().get(&DataKey::Escrow).unwrap(); escrow.admin.require_auth(); if escrow.status != EscrowStatus::Funded { if escrow.status == EscrowStatus::Paid { panic_with_error!(&env, Error::AlreadyPaid); } else { panic_with_error!(&env, Error::AlreadyRefunded); } } let protocol_config = escrow.protocol_config; let distributable = escrow.amount - protocol_config.fee_bps as i128 * escrow.amount / 10000; if distributable < 0 { panic_with_error!(&env, Error::InvalidAmount); } let payouts = compute_split(distributable, &recipients); let token_client = soroban_sdk::token::Client::new(&env, &escrow.token); for (recipient, amount) in &payouts { token_client.transfer(&env.current_contract_address(), recipient, amount); } escrow.status = EscrowStatus::Paid; env.storage().instance().set(&DataKey::Escrow, &escrow); env.storage().instance().extend_ttl(INSTANCE_LIFETIME_THRESHOLD, INSTANCE_BUMP_AMOUNT); payouts } pub fn refund(env: Env) { let mut escrow: Escrow = env.storage().instance().get(&DataKey::Escrow).unwrap(); let now = env.ledger().timestamp(); if now < escrow.deadline { escrow.admin.require_auth(); } if escrow.status != EscrowStatus::Funded { if escrow.status == EscrowStatus::Paid { panic_with_error!(&env, Error::AlreadyPaid); } else { panic_with_error!(&env, Error::AlreadyRefunded); } } let token_client = soroban_sdk::token::Client::new(&env, &escrow.token); token_client.transfer(&env.current_contract_address(), &escrow.sponsor, &escrow.amount); escrow.status = EscrowStatus::Refunded; env.storage().instance().set(&DataKey::Escrow, &escrow); env.storage().instance().extend_ttl(INSTANCE_LIFETIME_THRESHOLD, INSTANCE_BUMP_AMOUNT); } pub fn get_escrow(env: Env) -> Escrow { env.storage().instance().get(&DataKey::Escrow).unwrap() } } #[contracttype] #[derive(Clone, Debug, Eq, PartialEq)] enum DataKey { Escrow } fn compute_split(distributable: i128, recipients: &Vec<SplitRecipient>) -> Vec<(Address, i128)> { let mut payouts: Vec<(Address, i128)> = Vec::new(&soroban_sdk::Env::default()); let mut total_bps: u32 = 0; for r in recipients.iter() { total_bps += r.basis_points; } if total_bps != 10000 { panic_with_error!(&soroban_sdk::Env::default(), Error::InvalidSplit); } let mut remainders: Vec<(u32, u32, Address)> = Vec::new(&soroban_sdk::Env::default()); let mut allocated = 0i128; for r in recipients.iter() { let base = distributable * r.basis_points as i128 / 10000; let rem = (distributable * r.basis_points as i128) % 10000; payouts.push_back((r.address.clone(), base)); allocated += base; remainders.push_back((rem as u32, r.basis_points, r.address.clone())); } let dust = distributable - allocated; if dust > 0 { remainders.sort_by(|a, b| b.0.cmp(&a.0)); let mut i = 0; for mut r in remainders.iter() { if i >= dust { break; } let idx = payouts.iter().position(|(addr, _)| addr == &r.2).unwrap(); let (addr, amt) = payouts.get(idx).unwrap(); payouts.set(idx, &(addr, amt + 1)); i += 1; } } payouts }